 <!-- ============ CINEMATIC INTRO ============ -->
 <!--
-  ARCHITECTURE: The cinematic uses TWO layers to avoid mobile touch issues:
-  1. #nwg-cinematic — visual-only layer (pointer-events:none on everything)
-  2. #nwg-cine-touch — invisible tap target on top (catches play/unmute taps)
-  3. Buttons are OUTSIDE both layers with the highest z-index (200000+)
-
-  This prevents the classic mobile bug where a fixed overlay eats touch events
-  before they reach buttons, even when buttons have a higher z-index.
+  ARCHITECTURE v4 — iOS Safari fix:
+  On iOS Safari, position:fixed + pointer-events:none causes the overlay to
+  NOT paint above page content (WebKit compositing bug). Fix:
+  1. #nwg-cinematic gets pointer-events:auto when active (JS-controlled)
+  2. The wrapper itself catches taps (no separate touch overlay needed)
+  3. -webkit-transform:translateZ(0) forces GPU layer for correct stacking
+  4. Buttons sit OUTSIDE at z-index 200001+ (always above wrapper)
 -->
 <style>
   @keyframes nwgSpin{to{transform:rotate(360deg)}}
   @keyframes nwgPulse{0%,100%{opacity:.6}50%{opacity:1}}
   @keyframes nwgBtnPop{0%{transform:translateX(-50%) scale(1)}50%{transform:translateX(-50%) scale(.92)}100%{transform:translateX(-50%) scale(1)}}
-  /* Visual layer — NO pointer events at all */
-  #nwg-cinematic{position:fixed;inset:0;z-index:99999;background:#000;display:flex;align-items:center;justify-content:center;pointer-events:none}
-  #nwg-cinematic *{pointer-events:none}
+  /*
+    Cinematic overlay: pointer-events controlled by JS.
+    -webkit-transform:translateZ(0) forces a compositing layer on iOS Safari
+    so the overlay actually paints ABOVE page content.
+  */
+  #nwg-cinematic{
+    position:fixed;inset:0;z-index:99999;background:#000;
+    display:flex;align-items:center;justify-content:center;
+    pointer-events:none;
+    -webkit-transform:translateZ(0);transform:translateZ(0);
+    -webkit-tap-highlight-color:transparent;
+  }
   #nwg-cine-poster{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:1;transition:opacity .6s ease}
   #nwg-cine-video{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;z-index:2;opacity:0;transition:opacity .6s ease}
